function changeFeatureScope(value:'reviewed'|'all'){featureScope.value=value;if(value==='reviewed'){if(!isReadable(feature.value)&&reviewedFeatures.value.length)chooseFeature(reviewedFeatures.value.find(f=>f.volume===volume.value)?.id??reviewedFeatures.value[0].id);extraFeatures.value=extraFeatures.value.map((id,i)=>availableFeatures.value.some(f=>f.id===id)?id:defaultSettings().extraFeatures[i]);}}
function changeVolume(v:Volume){volume.value=v;const first=availableFeatures.value.find(f=>f.volume===v);if(first&&feature.value.volume!==v)chooseFeature(first.id);}
