  <template v-else-if="project.mode==='classification'"><h3>{{tr('modules.geolinguistics.compiled_by_jing_shaozi')}}</h3><p class="hint">{{tr('modules.geolinguistics.language_atlas_of_china_2nd_edition_chinese_dialects_county')}}</p><label>{{tr('modules.geolinguistics.original_worksheet')}}<select v-model="sheet"><option v-for="s in data.classification.sheets" :key="s.id" :value="s.id">{{s.name}} · {{s.rows.length}} {{tr('modules.geolinguistics.rows')}}</option></select></label><input v-model="classSearch" :placeholder="tr('modules.geolinguistics.search_site_or_classification_names')" :aria-label="tr('modules.geolinguistics.search_compilation')"/><label v-for="(name,depth) in [tr('modules.geolinguistics.dialect_macroregion'),tr('modules.geolinguistics.dialect_region'),tr('modules.geolinguistics.dialect_subgroup'),tr('modules.geolinguistics.dialect_sub_subgroup')]" :key="name">{{name}}<select :value="classFilters[depth]" @change="filterClass(depth,($event.target as HTMLSelectElement).value)"><option value="">{{tr('modules.geolinguistics.all')}}</option><option v-for="value in classOptions[depth]" :key="value" :value="value">{{value===unclassifiedClassFilter?tr('modules.geolinguistics.unclassified'):value}}</option></select></label><button @click="clearFilters">{{tr('modules.geolinguistics.clear_filters')}}</button><div class="summary"><b>{{classRows.length}}</b><span>{{tr('modules.geolinguistics.compiled_records')}}</span><b>{{countedPaths.length}}</b><span>{{tr('modules.geolinguistics.complete_classification_paths')}}</span></div><label>{{tr('modules.geolinguistics.counting_level')}}<select v-model.number="classDepth"><option :value="1">{{tr('modules.geolinguistics.macroregion')}}</option><option :value="2">{{tr('modules.geolinguistics.region')}}</option><option :value="3">{{tr('modules.geolinguistics.subgroup')}}</option><option :value="4">{{tr('modules.geolinguistics.sub_subgroup')}}</option></select></label><button @click="modal='paths'">{{tr('modules.geolinguistics.view_counted_classifications')}}</button><button @click="modal='ranking'">{{tr('modules.geolinguistics.compare_classification_counts_by_province')}}</button><small>{{tr('modules.geolinguistics.map_markers_are_representative_points_within_counties_click_to')}}</small></template>
